  const glowPath = (d, n, color = C.green, delay = 0, w = 5, extra = '') => `<g class="b${n}"><path class="flash flash${n}"${dl(delay)} d="${d}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"${extra}/></g>`;
