    const X0 = 110, K = 500 / 365, H = 62;
    const cols = [[C.mint, C.green], [C.peach, C.orange], [C.yellow, C.orange], [C.sky, C.blue]];
    const rowAt = (y, days, n, label) => {
      let s = at(n, 'fin', text(X0, y - 14, label, { size: 20, anchor: 'start' }));
      let x = X0;
      days.forEach((d, i) => {
        const w = d * K;
        s += `<g class="b${n}"><g class="grow grow${n}" style="transition-delay:${f(0.2 + i * 0.35)}s"><rect x="${f(x)}" y="${y}" width="${f(w)}" height="${H}" fill="${cols[i][0]}" stroke="${cols[i][1]}" stroke-width="2.5" ${i === 2 ? 'fill-opacity=".55"' : ''}/>${text(f(x + w / 2), y + 26, SEASONS[i], { size: 19 })}${text(f(x + w / 2), y + 52, `${d}일`, { size: 19, weight: 600 })}</g></g>`;
        x += w;
      });
      return s;
    };
    const OLDD = [85, 98, 73, 109], NOWD = [91, 118, 69, 87];
    body += rowAt(66, OLDD, 1, '1912~1940년');
    body += rowAt(206, NOWD, 2, '1991~2020년');
    // 3칸: 여름은 길어지고 겨울은 짧아졌다
