    const sumO = [0, 1, 2, 3, 4].map((i) => xOf(OLDD, i)), sumN = [0, 1, 2, 3, 4].map((i) => xOf(NOWD, i));
    body += shown(3, g('fin fin3', [1, 2, 3].map((i) => `<path d="M${f(sumO[i])} ${66 + H} L${f(sumN[i])} 206" stroke="${C.muted}" stroke-width="2.5" stroke-dasharray="6 5"/>`).join(''), 0.1));
    body += glowRect(sumN[1], 206, sumN[2] - sumN[1], H, 3, C.red, 0.4, 2) + glowRect(sumN[3], 206, sumN[4] - sumN[3], H, 3, C.blue, 1.0, 2);
    body += at(3, 'pop', tag(f((sumN[1] + sumN[2]) / 2), 304, '20일 늘어남', HOT, { size: 19 }), 0.6);
    body += at(3, 'pop', tag(f((sumN[3] + sumN[4]) / 2) - 6, 304, '22일 줄어듦', COLD, { size: 19 }), 1.2);
