    body += `<path d="${zig(282)} V291 ${zig(291).replace(/^M[\d.]+ [\d.]+/, '')}" fill="none"/>`;
    body += `<rect x="${X0 - 9}" y="281" width="34" height="11" fill="${C.paper}"/><path d="${zig(281)}" stroke="${C.ink}" stroke-width="2.5" fill="none"/><path d="${zig(292)}" stroke="${C.ink}" stroke-width="2.5" fill="none"/>`;
    body += text(xs(0), 330, '1912~1920', { size: 18, weight: 600, color: C.muted }) + text(xs(10) - 14, 330, '2011~2020', { size: 18, weight: 600, color: C.muted });
    const pts = T.map((t, i) => [xs(i), Y(t)]);
    // 1칸: 앞 절반, 2칸: 뒤 절반
    body += drawn(line(pts.slice(0, 6)), 1, C.red, 4.5, 0.3) + drawn(line(pts.slice(5)), 2, C.red, 4.5, 0.2);
    pts.forEach(([x, y], i) => { const n = i < 6 ? 1 : 2, s = i < 6 ? 0.3 + i * 0.27 : 0.2 + (i - 5) * 0.3; body += at(n, 'pop', `<circle cx="${f(x)}" cy="${f(y)}" r="6" fill="white" stroke="${C.red}" stroke-width="3.5"/>`, f(s)); });
