    // 3칸: 1.9 ℃ 오름, 지구도 데워진다
    body += at(3, 'fin', `<path d="M${xs(0) + 10} ${f(Y(12.0))} H${xs(10) + 10}" stroke="${C.muted}" stroke-width="2" stroke-dasharray="6 5"/>` + solid(xs(10) + 4, Y(12.0) - 4, xs(10) + 4, Y(13.9) + 10, C.orange, 4), 0.1);
    body += at(3, 'pop', tag(xs(8) - 4, Y(12.0) + 30, '1.9 ℃ 오름', HOT, { size: 20 }), 0.8);
    body += at(3, 'pop', globe(206, 104, 42) + thermo(270, 64, 132, 'tmg', C.red, 14), 0.5);
    css += level(id, 'tmg', [0.3, 0.3, 0.3, 0.85]);
