    const old = fern(92, 236) + fern(140, 244) + fish(300, 220) + fish(352, 240) + fish(470, 222) + `<path d="M520 236 q8 -14 16 0 q8 -14 16 0" stroke="${C.purple}" stroke-width="3" fill="none"/>`;
    body += `<g class="b1 h2">${g('drop drop1', old, 0.2)}</g>`;
