    const fuels = [[120, 290, coal, '석탄'], [320, 288, oil, '석유'], [500, 284, gas, '천연가스']];
    fuels.forEach(([x, y, fn, label], i) => { body += at(2, 'pop', fn(x, y), 0.3 + i * 0.4) + at(2, 'pop', tag(x, 336, label, PLAIN, { size: 20 }), 0.5 + i * 0.4); });
    // 3칸: 공장·자동차에서 태우면 온실가스
